package com.hbm.client.reactor.rbmk.panels;
import com.google.gson.*;
import com.hbm.client.model.*;
import java.util.*;
import java.util.function.Function;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.LightTexture;
import net.minecraft.client.renderer.block.model.*;
import net.minecraft.client.renderer.texture.TextureAtlasSprite;
import net.minecraft.client.resources.model.*;
import net.minecraft.core.Direction;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.neoforge.client.model.geometry.*;
import net.neoforged.neoforge.client.model.pipeline.QuadBakingVertexConsumer;
import org.joml.Matrix3f;
import org.joml.Matrix4f;
import org.joml.Vector3f;
/** Bakes the actual source inventory cube and explicit OBJ transforms/parts into a native model for every modern hand context. */
public record RbmkPanelInventoryGeometry(JsonArray overlays)implements IUnbakedGeometry<RbmkPanelInventoryGeometry>{
    public static final IGeometryLoader<RbmkPanelInventoryGeometry> LOADER=(json,context)->new RbmkPanelInventoryGeometry(json.getAsJsonArray("overlays"));
    @Override public BakedModel bake(IGeometryBakingContext context,ModelBaker baker,Function<Material,TextureAtlasSprite> sprites,ModelState state,ItemOverrides overrides){var baseSprite=sprites.apply(context.getMaterial("all"));var result=new SimpleBakedModel.Builder(false,true,true,context.getTransforms(),overrides).particle(baseSprite);var bakery=new FaceBakery();for(var side:Direction.values()){float[] uv=switch(side){case DOWN,UP,SOUTH->new float[]{4,0,16,16};case NORTH->new float[]{0,0,12,16};default->new float[]{0,0,16,16};};var original=bakery.bakeQuad(new Vector3f(4,0,0),new Vector3f(16,16,16),new BlockElementFace(null,-1,"",new BlockFaceUV(uv,0)),baseSprite,side,BlockModelRotation.X0_Y0,null,false);var vertices=original.getVertices().clone();var rotated=side.getAxis()==Direction.Axis.Y?side:side.getCounterClockWise();int normal=(rotated.getStepX()*127&255)|((rotated.getStepY()*127&255)<<8)|((rotated.getStepZ()*127&255)<<16);for(int i=0;i<4;i++){int offset=i*8;float x=Float.intBitsToFloat(vertices[offset]),z=Float.intBitsToFloat(vertices[offset+2]);vertices[offset]=Float.floatToRawIntBits(z);vertices[offset+2]=Float.floatToRawIntBits(1-x);vertices[offset+7]=normal;}result.addUnculledFace(new BakedQuad(vertices,-1,rotated,baseSprite,false,false));}
        for(var value:overlays){var overlay=value.getAsJsonObject();var matrix=new Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(-90));for(var op:overlay.getAsJsonArray("transforms")){var row=op.getAsJsonObject();if(row.has("translate")){var v=row.getAsJsonArray("translate");matrix.translate(v.get(0).getAsFloat(),v.get(1).getAsFloat(),v.get(2).getAsFloat());}if(row.has("scale")){var v=row.getAsJsonArray("scale");matrix.scale(v.get(0).getAsFloat(),v.get(1).getAsFloat(),v.get(2).getAsFloat());}if(row.has("rotate")){var v=row.getAsJsonArray("rotate");matrix.rotate((float)Math.toRadians(v.get(0).getAsFloat()),v.get(1).getAsFloat(),v.get(2).getAsFloat(),v.get(3).getAsFloat());}}
            var normalMatrix=new Matrix3f(matrix).invert().transpose();var sprite=sprites.apply(context.getMaterial(overlay.get("texture").getAsString()));var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),ResourceLocation.parse(overlay.get("model").getAsString()));String part=overlay.has("part")?overlay.get("part").getAsString():null;int color=overlay.has("color")?overlay.get("color").getAsInt():-1;boolean bright=overlay.has("fullbright")&&overlay.get("fullbright").getAsBoolean();var solid=overlay.has("solid_uv")?overlay.getAsJsonArray("solid_uv"):null;var uvScale=overlay.has("uv_scale")?overlay.getAsJsonArray("uv_scale"):null;
            for(var face:mesh.faces()){if(part!=null&&!face.legacyPart().equalsIgnoreCase(part))continue;var corners=face.corners();if(corners.size()==3)corners=List.of(corners.get(0),corners.get(1),corners.get(2),corners.get(2));if(corners.size()!=4)throw new IllegalStateException("Source panel OBJ polygon "+corners.size());var out=new QuadBakingVertexConsumer();var faceNormal=face.normal();var direction=new Vector3f(faceNormal.x(),faceNormal.y(),faceNormal.z()).mul(normalMatrix).normalize();out.setDirection(Direction.getNearest(direction.x,direction.y,direction.z));out.setSprite(sprite);out.setShade(true);out.setHasAmbientOcclusion(false);for(var corner:corners){var source=mesh.positions().get(corner.position());var position=new Vector3f(source.x(),source.y(),source.z()).mulPosition(matrix);var sourceNormal=corner.normal()>=0?mesh.normals().get(corner.normal()):face.normal();var normal=new Vector3f(sourceNormal.x(),sourceNormal.y(),sourceNormal.z()).mul(normalMatrix).normalize();var uv=corner.texture()>=0?mesh.textureCoordinates().get(corner.texture()):new WavefrontMesh.TexCoord(0,0,0);float u=solid!=null?solid.get(0).getAsFloat():uv.u(),v=solid!=null?solid.get(1).getAsFloat():1-uv.v();out.addVertex(position.x,position.y,position.z).setColor(color).setUv(sprite.getU(u*(uvScale!=null?uvScale.get(0).getAsFloat():1)),sprite.getV(v*(uvScale!=null?uvScale.get(1).getAsFloat():1))).setLight(bright?LightTexture.FULL_BRIGHT:0).setNormal(normal.x,normal.y,normal.z);}result.addUnculledFace(out.bakeQuad());}}
        return result.build(context.getRenderType(ResourceLocation.withDefaultNamespace("cutout")));}
}
